INSERT INTO SCM_MGR.GT_DM35_RAW_DATA (VERSION_NO, CUTOFF_YYYYMMDD, DIVISION_ID, PROJECT_CODE, SCM_SITE_ID, PLANT_SITE_ID, ITEM_ID , INCOTERMS, DOM_EXP, FCST_TYPE, MEASURE, MEASURE_GROUP, YYYYMMDD, QTY, PLAN_RESULT, GUBUN, CREATE_DATE , LAST_UPDATED_BY, SENDER_CODE, SENDER_NAME , AS_FROM_SITE, CELL_PROD_SITE_ID ) SELECT CASE WHEN :B1 = '82' THEN E.VERSION_NO_W ELSE A.VERSION_NO END AS VERSION_NO , A.CUTOFF_YYYYMMDD , A.DIVISION_ID , A.PROJECT_CODE , A.SCM_SITE_ID , A.PLANT_SITE_ID , A.ITEM_ID , A.INCOTERMS , A.DOM_EXP , A.FCST_TYPE , A.MEASURE , CASE WHEN A.DIVISION_ID = '40' AND B.MEASURE_GROUP IS NULL THEN 'MKT_FCST_RP' WHEN A.DIVISION_ID = '40' THEN B.MEASURE_GROUP ELSE '' END AS MEASURE_GROUP , A.YYYYMMDD , A.QTY , 'P', 3 , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN (SELECT MAX(LS.CREATE_DATE) FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder')) WHEN A.MEASURE IN ('CUST_FCST', 'CUSTOMER FCST') THEN (SELECT MAX(LS.CREATE_DATE) FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE IN ('CUST_FCST', 'CUSTOMER FCST')) WHEN A.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN (SELECT MAX(LS.CREATE_DATE) FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST')) ELSE (SELECT LS.CREATE_DATE FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE = A.MEASURE) END) , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'Customer FCST') THEN (CASE WHEN A.LAST_UPDATED_BY LIKE '%robot' THEN A.LAST_UPDATED_BY || '_RPA' ELSE A.LAST_UPDATED_BY END) WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN (CASE WHEN NVL(A.ATTRIBUTE5, '@#@#@#') = '@#@#@#' THEN (SELECT MAX(ES.SENDER_NAME) FROM SCM_MGR.GT_DM35_EDI_SENDER ES WHERE ES.SCM_SITE_ID = A.SCM_SITE_ID) || '_EDI' ELSE A.ATTRIBUTE5 || '_' || A.LAST_UPDATED_BY END) WHEN A.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') THEN (SELECT MAX(LS.LAST_UPDATED_BY) FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST') AND LS.CREATE_DATE = (SELECT MAX(LS2.CREATE_DATE) FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS2 WHERE LS2.DIVISION_ID = A.DIVISION_ID AND LS2.PROJECT_CODE = A.PROJECT_CODE AND LS2.SCM_SITE_ID = A.SCM_SITE_ID AND LS2.ITEM_ID = A.ITEM_ID AND LS2.DOM_EXP = A.DOM_EXP AND LS2.FCST_TYPE = A.FCST_TYPE AND LS2.INCOTERMS = A.INCOTERMS AND LS2.VERSION_NO = A.VERSION_NO AND LS2.MEASURE IN ('RTF', 'RTF_SYS_RP', 'MKT_FCST'))) ELSE (SELECT LS.LAST_UPDATED_BY FROM SCM_MGR.GT_DM35_T_LAST_SETUP_C LS WHERE LS.DIVISION_ID = A.DIVISION_ID AND LS.PROJECT_CODE = A.PROJECT_CODE AND LS.SCM_SITE_ID = A.SCM_SITE_ID AND LS.ITEM_ID = A.ITEM_ID AND LS.DOM_EXP = A.DOM_EXP AND LS.FCST_TYPE = A.FCST_TYPE AND LS.INCOTERMS = A.INCOTERMS AND LS.VERSION_NO = A.VERSION_NO AND LS.MEASURE = A.MEASURE) END) , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN (CASE WHEN NVL(A.ATTRIBUTE4, '@#@#@#') = '@#@#@#' THEN (SELECT MAX(ES.SENDER_CODE) FROM SCM_MGR.GT_DM35_EDI_SENDER ES WHERE ES.SCM_SITE_ID = A.SCM_SITE_ID) ELSE A.ATTRIBUTE4 END) ELSE NULL END) , (CASE WHEN A.MEASURE IN ('CUST_FCST', 'CUST_FCST_EDI', 'Immidiate', 'Planning_Forecast', 'Commercial_Agreement', 'Firm_Temp', 'Manumacturing_Material_Temp', 'Material_Temp', 'Backorder') THEN (CASE WHEN NVL(A.ATTRIBUTE5, '@#@#@#') = '@#@#@#' THEN (SELECT MAX(ES.SENDER_NAME) FROM SCM_MGR.GT_DM35_EDI_SENDER ES WHERE ES.SCM_SITE_ID = A.SCM_SITE_ID) ELSE A.ATTRIBUTE5 END) ELSE NULL END) , CASE WHEN A.DIVISION_ID IN ('81', '82') THEN A.ATTRIBUTE10 ELSE NULL END AS AS_FROM_SITE , A.CELL_PROD_SITE_ID FROM ( SELECT F.DIVISION_ID, F.PROJECT_CODE, F.SCM_SITE_ID, F.PLANT_SITE_ID, F.ITEM_ID, F.DOM_EXP, F.FCST_TYPE, F.INCOTERMS, F.MEASURE, F.YYYYMMDD, F.QTY, F.ATTRIBUTE10, '-' AS CELL_PROD_SITE_ID , F.LAST_UPDATED_BY, F.LAST_UPDATE_DATE, F.ATTRIBUTE4, F.ATTRIBUTE5, F.ATTRIBUTE9, F.VERSION_NO, F.CUTOFF_TYPE, F.CUTOFF_YYYYMMDD FROM SCM_MGR.DM_PLN_MKT_FCST_C F WHERE (CASE WHEN :B1 = '40' THEN 1 ELSE 2 END) = 2 UNION ALL SELECT F.DIVISION_ID, F.PROJECT_CODE, F.SCM_SITE_ID, F.PLANT_SITE_ID, F.ITEM_ID, F.DOM_EXP, F.FCST_TYPE, F.INCOTERMS, F.MEASURE, F.YYYYMMDD, F.QTY, F.ATTRIBUTE10, F.CELL_PROD_SITE_ID , F.LAST_UPDATED_BY, F.LAST_UPDATE_DATE, F.ATTRIBUTE4, F.ATTRIBUTE5, F.ATTRIBUTE9, F.VERSION_NO, F.CUTOFF_TYPE, F.CUTOFF_YYYYMMDD FROM SCM_MGR.DM_PLN_CFM_MKT_DEMAND_PLAN_C F WHERE (CASE WHEN :B1 = '40' THEN 1 ELSE 2 END) = 1 ) A JOIN SCM_MGR.GT_DM35_SEL_MEASURE B ON A.MEASURE = B.MEASURE JOIN SCM_MGR.SCM_MST_SITE C ON A.DIVISION_ID = C.DIVISION_ID AND A.SCM_SITE_ID = C.SCM_SITE_ID AND C.VALID_YN = 'Y' JOIN SCM_MGR.GT_DM35_VERSION E ON A.VERSION_NO = E.VERSION_NO AND (E.VERSION_NO LIKE '%MF%' OR E.VERSION_NO LIKE '%SF%') WHERE A.YYYYMMDD >= :B3 AND A.YYYYMMDD <= :B2 AND A.YYYYMMDD >= E.NOW_YYYYMMDD AND A.DIVISION_ID = :B1 AND A.MEASURE NOT IN ('CUST_FCST_EDI_ORG', 'Immidiate[Org.]', 'Planning_Forecast[Org.]', 'Commercial_Agreement[Org.]', 'Firm_Temp[Org.]', 'Manumacturing_Material_Temp[Org.]', 'Material_Temp[Org.]', 'Backorder[Org.]') AND A.QTY <> 0